import unittest
from tags import normalize_tags

class Tests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(normalize_tags([" A "]), ["a"])

    def test_trim_and_casefold(self):
        self.assertEqual(normalize_tags(["  Hello  ", "WORLD\t"]), ["hello", "world"])

    def test_omits_empty_strings(self):
        self.assertEqual(normalize_tags(["", "   ", "\n", "tag"]), ["tag"])

    def test_removes_duplicates_preserving_first_order(self):
        self.assertEqual(normalize_tags(["first", "SECOND", "First", "second", "third"]), ["first", "second", "third"])

    def test_max_three_unique_tags(self):
        self.assertEqual(normalize_tags(["t1", "t2", "t3"]), ["t1", "t2", "t3"])
        with self.assertRaisesRegex(ValueError, "^too many tags$"):
            normalize_tags(["t1", "t2", "t3", "t4"])

    def test_does_not_mutate_input(self):
        original = [" B ", "A", "b"]
        original_copy = list(original)
        res = normalize_tags(original)
        self.assertEqual(res, ["b", "a"])
        self.assertEqual(original, original_copy)

    def test_non_str_element_raises_type_error(self):
        with self.assertRaisesRegex(TypeError, "^tag must be str$"):
            normalize_tags(["valid", 123])
        with self.assertRaisesRegex(TypeError, "^tag must be str$"):
            normalize_tags([None])

