        if not isinstance(row, (tuple, list)) or len(row) != 2:
            raise ValueError("fila inválida")
        name, count = row
        if not isinstance(name, str):
            raise ValueError("fila inválida")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0:
            raise ValueError("fila inválida")

        trimmed = name.strip()
        display_name = trimmed if trimmed else "(sin nombre)"
        validated_rows.append((display_name, count))

    if not validated_rows:
        return "Sin resultados — todavía"

    lines = []
    for name, count in validated_rows[:limit]:
        lines.append(f"• {name}: {count}")

    if len(validated_rows) > limit:
        overflow = len(validated_rows) - limit
        lines.append(f"… y {overflow} más")

    return "\n".join(lines)

